import{_ as a,C as s,c as r,o as i,a3 as e,G as n}from"./chunks/framework.Dokpd4od.js";const y=JSON.parse('{"title":"Inventory adjustments","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/inventories/adjustments/inventory-adjustments.md","filePath":"master/supply-chain/inventories/adjustments/inventory-adjustments.md","lastUpdated":1792041590000}'),d={name:"master/supply-chain/inventories/adjustments/inventory-adjustments.md"};function l(c,t,u,h,g,p){const o=s("ImagePopup");return i(),r("div",null,[t[0]||(t[0]=e('<h1 id="inventory-adjustments" tabindex="-1">Inventory adjustments <a class="header-anchor" href="#inventory-adjustments" aria-label="Permalink to &quot;Inventory adjustments&quot;">​</a></h1><p>An inventory adjustment is a physical count. You walk the shelves, enter what you find, and Aureus works out the difference from what the system expected. When you apply the count, the stock numbers are corrected.</p><blockquote><p><strong>In simple words:</strong> Type what you counted, check the difference, then click Apply.</p></blockquote><p>Open it from <code>Inventory → Operations → Adjustments → Quantities</code>. The page title is <strong>Quantity Adjustments</strong>.</p><div class="warning custom-block"><p class="custom-block-title">Before you start</p><p>The <strong>Location</strong>, <strong>Lot / Serial Numbers</strong> and <strong>Package</strong> columns appear only when the matching settings are on. Check <code>Inventory → Settings → Manage Warehouses → Locations</code>, <code>Manage Traceability → Lots &amp; Serial Numbers</code> and <code>Manage Operations → Packages</code>.</p></div><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The scheduled date of a count comes from the annual inventory date. Set it in <code>Inventory → Settings → Manage Operations</code>.</p><ul><li><strong>Annual Inventory Day:</strong> the day of the month, for example 31.</li><li><strong>Annual Inventory Month:</strong> the month, for example December.</li></ul><p>With 31 and December, new count rows get the scheduled date 31 December.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The list shows one row per product, location, lot and package. It has these tabs:</p><table tabindex="0"><thead><tr><th>Tab</th><th>Shows</th></tr></thead><tbody><tr><td><strong>Default</strong></td><td>All rows</td></tr><tr><td><strong>Internal Locations</strong></td><td>Stock inside your own warehouse</td></tr><tr><td><strong>Transit Locations</strong></td><td>Stock in transit locations</td></tr><tr><td><strong>On Hand</strong></td><td>Rows with a quantity above zero</td></tr><tr><td><strong>To Count</strong></td><td>Rows whose scheduled date is still ahead</td></tr><tr><td><strong>To Apply</strong></td><td>Rows that already have a counted quantity</td></tr></tbody></table>',12)),n(o,{src:"/images1/inventory/adj_quantities_list.png",alt:"Quantity Adjustments list with the tabs Internal Locations, Transit Locations, On Hand, To Count and To Apply"}),t[1]||(t[1]=e('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong>Location, Product, Lot / Serial Numbers, Package:</strong> where the stock is and what it is.</li><li><strong>On Hand Quantity:</strong> what the system believes is there.</li><li><strong>Counted Quantity:</strong> what you found. You type it in the row.</li><li><strong>Difference:</strong> counted minus on hand. It stays empty until you count.</li><li><strong>Scheduled At:</strong> the date the count is due.</li><li><strong>User:</strong> who is responsible.</li></ul><p>You can also show <strong>Storage Category</strong>, <strong>Product Category</strong>, <strong>Available Quantity</strong> and <strong>Company</strong>. Use <strong>Group by</strong> for Product, Product Category, Location, Storage Category, Lot / Serial Numbers, Package or Company.</p><h2 id="count-an-existing-row" tabindex="-1">Count an existing row <a class="header-anchor" href="#count-an-existing-row" aria-label="Permalink to &quot;Count an existing row&quot;">​</a></h2><p>The company counts Camping Hammock at <code>WH/Stock</code>. The system says 110.</p><ol><li>Open <code>Inventory → Operations → Adjustments → Quantities</code>.</li><li>Search for <strong>Camping Hammock</strong>.</li><li>Click the <strong>Counted Quantity</strong> box on the <code>WH/Stock</code> row.</li><li>Type <strong>108</strong> and leave the box. A message says <strong>Quantity updated</strong>.</li></ol>',6)),n(o,{src:"/images1/inventory/adj_counted_quantity.png",alt:"Camping Hammock row in WH/Stock with Counted Quantity 108 and Difference -2"}),t[2]||(t[2]=e('<p>The <strong>Difference</strong> now reads -2. The row also appears in the <strong>To Apply</strong> tab.</p><h2 id="apply-or-clear-the-count" tabindex="-1">Apply or clear the count <a class="header-anchor" href="#apply-or-clear-the-count" aria-label="Permalink to &quot;Apply or clear the count&quot;">​</a></h2><p>Two row actions appear once a count exists.</p><ol><li>Click <strong>Apply</strong> to write the count into stock. A message says <strong>Quantity changes applied</strong>. On hand becomes 108.</li><li>Click <strong>Clear</strong> to throw the count away instead. A message says <strong>Quantity changes cleared</strong>. On hand stays 110.</li></ol>',4)),n(o,{src:"/images1/inventory/adj_apply_clear.png",alt:"Row actions Apply and Clear on the Camping Hammock row in the To Apply tab"}),t[3]||(t[3]=e('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Review the <strong>To Apply</strong> tab before you apply. It lists every pending count in one place.</p></div><h2 id="add-a-quantity" tabindex="-1">Add a quantity <a class="header-anchor" href="#add-a-quantity" aria-label="Permalink to &quot;Add a quantity&quot;">​</a></h2><p>Use <strong>Add Quantity</strong> when a product has no row at that location yet, for example after finding unrecorded stock.</p><ol><li>Click <strong>Add Quantity</strong>. The <strong>Create Product Quantity</strong> window opens.</li><li>Fill in the fields.</li><li>Click <strong>Create</strong>.</li></ol>',4)),n(o,{src:"/images1/inventory/adj_add_quantity.png",alt:"Create Product Quantity window with Location WH/Stock, Product Camping Hammock and Counted Quantity 5"}),t[4]||(t[4]=e('<ul><li><strong><em>Location:</em></strong> required. Default is <code>WH/Stock</code>.</li><li><strong><em>Product:</em></strong> required.</li><li><strong><em>Package:</em></strong> optional. Pick it when the goods sit in a package.</li><li><strong><em>Counted Quantity:</em></strong> required. Default is 0.</li><li><strong><em>Scheduled At:</em></strong> the due date. It defaults to the annual inventory date.</li></ul><p>A message says <strong>Quantity added</strong>. If a row for the same product and location already exists, Aureus warns you to update the existing quantity instead.</p><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>When you apply a count, Aureus creates a stock move for the difference. For a loss of 2 units, the stock leaves <code>WH/Stock</code> and goes to <code>Virtual Locations/Inventory Adjustment</code>. For a gain, the move runs the other way. You can see it in <a href="./../reporting/moves-history.html">Moves history</a>.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Where</th><th>Effect</th></tr></thead><tbody><tr><td>Type a <strong>Counted Quantity</strong></td><td>Row</td><td>Saves the count and fills <strong>Difference</strong></td></tr><tr><td><strong>Apply</strong></td><td>Row with a count</td><td>Corrects stock and clears the count</td></tr><tr><td><strong>Clear</strong></td><td>Row with a count</td><td>Removes the count, stock unchanged</td></tr><tr><td><strong>Add Quantity</strong></td><td>Page header</td><td>Creates a new stock row</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Adjustments overview</a></li><li><a href="./scrap.html">Scrap</a></li><li><a href="./../reporting/stock-report.html">Stock report</a></li><li><a href="./../barcode/scan-adjustments.html">Scan adjustments</a></li><li><a href="./../get-started/inventory-settings.html">Inventory settings</a></li></ul>',8))])}const _=a(d,[["render",l]]);export{y as __pageData,_ as default};
